[1524] = { en = "Call of Fire", tier = 1,
  t = "De roep van het vuur",
  d = "Je bent sterk genoeg om de totem van vuur te gebruiken. Maar dat betekent niet dat je er klaar voor bent.$B$BLangs de Southfury River in Durotar, voor de Great Sea, ligt een verborgen pad. Het gaat naar een van de hoogste toppen van het land. Klim naar boven. Daar vind je een van onze heilige plaatsen: de Shrine of the Dormant Flame. Telf Joolam waakt erover.$B$BBreng deze fakkel naar hem. Hij laat zien dat je het vuur probeert te temmen. Steek hem aan bij de vuurschaal van het heiligdom en breng hem brandend bij mij terug. Dan zorg ik dat je de totem van vuur krijgt.",
  o = "Breng de Torch of the Dormant Flame naar Telf Joolam in Durotar.",
  p = "Gegroet, $N. Je bent bij de Shrine of the Dormant Flame. Alleen wie genoeg weet van de kunsten van de sjamaan, leert ooit de geheimen van deze plek en haar kracht. Het spijt me dat je zo'n lange reis hebt gemaakt en nu terug moet. De tocht hierheen is tenslotte verre van veilig. Maar ik ben de bewaker van het heiligdom, en ik kan niet zomaar iedereen hier laten rondlopen.",
  c = "Ah, mijn fout, $N. Sorry. Ik zag niet dat je de Torch had. Ik ben blij je te leren kennen.$B$BVeel avonturiers komen hier. Ze zoeken verloren schatten, of magische wezens om te doden. Maar ze moeten weer weg, want het heiligdom lijkt leeg. Wij weten de waarheid, nietwaar, $N?$B$BDit heiligdom heeft een groter geheim, verborgen voor de gewone leden van de Horde. Voor ons is het heilig.",
  g = { {"verborgen", "hidden"}, {"toppen", "peaks (top)"}, {"waakt erover", "watches over it (waken)"}, {"fakkel", "torch"}, {"temmen", "to tame"}, {"Steek hem aan", "light it (aansteken)"}, {"vuurschaal", "brazier"}, {"heiligdom", "shrine, sanctuary"}, {"brandend", "burning, aflame"}, {"kunsten", "arts (kunst)"}, {"tenslotte", "after all"}, {"verre van", "far from"}, {"bewaker", "keeper, guard"}, {"avonturiers", "adventurers (avonturier)"}, {"nietwaar", "isn't it, don't we"} },
},

[1525] = { en = "Call of Fire", tier = 1,
  t = "De roep van het vuur",
  d = "Maar je bent hier niet voor een geschiedenisles, toch? Je komt voor de Eternal Flame en de vuurtotem.$B$BDe eerste stap is een sapta maken die jou aan de vlam bindt.$B$BIk kan de vuursapta voor je maken als je me twee dingen brengt. Het eerste is vuurteer. Dat is iets eenvoudigs. De magiërs van de Razormane in het oosten van de Barrens hebben het meestal bij zich.$B$BHet tweede is gevaarlijker: een zakje met reagentia van een van de sekteleden van de Burning Blade. Je vindt ze in een grot boven de ravijnen, ten noordoosten van Razor Hill.",
  o = "Breng 1 Fire Tar en 1 Reagent Pouch naar Telf Joolam in Durotar.",
  p = "Ik heb genoeg ingrediënten voor een sapta van vuur, als jij het zakje met reagentia en wat vuurteer vindt. De fanatici van de Burning Blade hebben in die zakjes de juiste onderdelen voor de meeste van hun spreuken. En meestal hebben ze genoeg van de dingen die ik nodig heb. Dan hoeven we niet veel verder naar iets anders te zoeken.$B$BWe maken sapta's altijd van ingrediënten die nauw verbonden zijn met hun eigen element. De heksenmeesters zijn verbonden met vuur. Dat maakt ons werk makkelijker.",
  c = "Deze zijn prima, $N.$B$BVuur is meer dan chaos en vernietiging. Onthoud dat goed. Vuur gaat ook over leven en schepping. Alle dingen zijn zo met elkaar verbonden. Krachten werken tegen elkaar in, maar tegelijk kan de ene niet bestaan zonder de andere. Ze doven elkaar uit, maar ze geven elkaar ook betekenis. Onthoud dit altijd.$B$BAls je verschillende soorten magie samen gebruikt, laat je niet alleen echte vaardigheid zien. Je laat ook grote wijsheid zien.",
  g = { {"geschiedenisles", "history lesson"}, {"vuurtotem", "fire totem"}, {"vuurteer", "fire tar"}, {"magiërs", "mages, spellcasters (magiër)"}, {"zakje", "pouch, small bag"}, {"reagentia", "reagents (reagens)"}, {"sekteleden", "cultists (sektelid)"}, {"grot", "cave"}, {"fanatici", "fanatics (fanaticus)"}, {"onderdelen", "components (onderdeel)"}, {"nauw", "closely"}, {"heksenmeesters", "warlocks (heksenmeester)"}, {"schepping", "creation"}, {"doven elkaar uit", "extinguish one another (uitdoven)"}, {"betekenis", "meaning"} },
},

[1464] = { en = "Fire Sapta", tier = 1,
  t = "Sapta van vuur",
  o = "Spreek met Telf Joolam voor een nieuwe Fire Sapta.",
  p = "Spreek met Telf Joolam voor een nieuwe Fire Sapta.",
  c = "Moge het vuur branden in je hart, $N.$B$BDe elementen wachten op je.",
  g = { {"Spreek", "speak (spreken)"}, {"nieuwe", "another, new (nieuw)"}, {"Moge", "may (mogen)"}, {"branden", "to burn"}, {"wachten op", "to wait for, await"} },
},

[1526] = { en = "Call of Fire", tier = 1,
  t = "De roep van het vuur",
  d = "De vuursapta is klaar. Het is tijd dat je de vlam onder ogen komt. Gebruik de sapta bij het heiligdom en ga naar de top van de berg. Daar is een verschijning van het vuur. Je moet tegen hem vechten. Hij valt niet aan voordat je klaar bent. Maar hij zal merken dat je hem kunt zien.$B$BVersla hem snel, $N, want hoe langer je erover doet, hoe sterker hij wordt. Is hij verslagen? Leg dan zijn gloeiende kolen in de vuurschaal en steek de fakkel aan.",
  o = "Versla de Minor Manifestation of Fire en leg de Glowing Ember in de vuurschaal boven op de Shrine of Eternal Flame.",
  p = "De vuurschaal is ongeveer een derde zo hoog als jij. Hij ziet er gewoon uit, behalve de opschriften op de gladde metalen stangen. Het metaal is niet aangetast door het weer. De kom bovenop voelt koel aan.",
  c = "Er gaat een witheet vuur aan in de kom als je de gloeiende kool erin legt. Je voelt de magie van de sapta door je lichaam stromen. Het vuur danst ritmisch voor je.$B$BJe houdt de bovenkant van de fakkel in de schaal. Meteen vat hij vlam.",
  g = { {"vuursapta", "fire sapta"}, {"onder ogen komt", "face (onder ogen komen)"}, {"verschijning", "manifestation, apparition"}, {"valt niet aan", "does not attack (aanvallen)"}, {"Versla", "defeat (verslaan)"}, {"gloeiende", "glowing (gloeiend)"}, {"kolen", "embers, coals (kool)"}, {"vuurschaal", "brazier"}, {"opschriften", "inscriptions (opschrift)"}, {"stangen", "rails, rods (stang)"}, {"aangetast", "affected, worn (aantasten)"}, {"kom", "bowl"}, {"witheet", "white-hot"}, {"ritmisch", "rhythmically"}, {"vat hij vlam", "it catches fire (vlam vatten)"} },
},

[1527] = { en = "Call of Fire", tier = 1,
  t = "De roep van het vuur",
  d = "Je houdt de fakkel stevig vast. Je draait je om, weg van de vuurschaal, en kijkt uit over Durotar. Je voelt een opwinding die aan je geest trekt. De wind wordt sterker en laat de vlam wild dansen.$B$BJe gaat het pad af, terug naar de Barrens, op zoek naar Kranal Fiss.",
  o = "Breng de Torch of Eternal Flame naar Kranal Fiss in de Barrens.",
  p = "Ja, $N? Wat heb je daar?",
  c = "Je geest brandt feller dan elke fakkel die ik ooit heb gezien, $N. Daar mag je trots op zijn.$B$BAls je dit pad blijft volgen, zul je de elementen bevelen. Onze broeders zullen bij jou leiding en wijsheid zoeken. Laat mij de eerste zijn die je feliciteert. Hier is je nieuwste totem.",
  g = { {"stevig", "firmly"}, {"draait je om", "turn around (zich omdraaien)"}, {"kijkt uit over", "look out over (uitkijken)"}, {"opwinding", "excitement"}, {"trekt", "pulls, tugs (trekken)"}, {"op zoek naar", "in search of"}, {"feller", "brighter (fel)"}, {"bevelen", "to command"}, {"broeders", "brethren (broeder)"}, {"leiding", "guidance"}, {"feliciteert", "congratulate (feliciteren)"} },
},

[1528] = { en = "Call of Water", tier = 1,
  t = "De roep van het water",
  d = "Water is in je toekomst, man. Ik zie dat je al sterk bent in de wegen van het vuur. En ik denk dat je klaar bent om met Islen te praten.$B$BIslen woont aan de kust van de Barrens. Ga naar het zuiden langs de Southfury River, dan kun je haar niet missen. Kijk naar de grote haai! Ze is sterk in de wegen van de elementen. Ze kan je de wegen van het water leren... als je denkt dat je klaar bent.$B$BZe is makkelijk te vinden. Ga alleen niet te ver naar het zuiden. Ze woont net voorbij Ratchet.",
  o = "Zoek Islen Waterseer in de Barrens.",
  c = "De wind komt snel vanaf de horizon naar je toe. De aarde staat stevig onder je voeten. En je geest is al verwarmd door het vuur. Ik zou zeggen: het is tijd dat je leert over de zuiverheid van water.$B$BJe pad heeft je tot hier gebracht. Je geest zal je de kracht geven om nog verder te gaan. Maar de eerste stap moet jij zelf zetten.",
  g = { {"toekomst", "future"}, {"wegen", "ways (weg)"}, {"kust", "coast"}, {"missen", "to miss"}, {"haai", "shark"}, {"net voorbij", "just beyond"}, {"horizon", "horizon"}, {"stevig", "steady, firm"}, {"verwarmd", "warmed (verwarmen)"}, {"zuiverheid", "purity"}, {"zetten", "to take (a step), to set"} },
},

[1529] = { en = "Call of Water", tier = 1,
  t = "De roep van het water",
  d = "Het is lang geleden dat je voor het laatst getest bent, $N. Je bent tot nu toe geduldig geweest in je studie. Maar nu is het tijd dat je meer leert. Het is tijd dat je leert over de zuiverheid van water.$B$BZoek Islen Waterseer in de Barrens. Ze is aan de oostkust, ten zuiden van de Southfury River en Ratchet. Je vindt haar daar bij haar vissershut. Succes, $N.",
  o = "Zoek Islen Waterseer in de Barrens.",
  c = "De wind komt snel vanaf de horizon naar je toe. De aarde staat stevig onder je voeten. En je geest is al verwarmd door het vuur. Ik zou zeggen: het is tijd dat je leert over de zuiverheid van water.$B$BJe pad heeft je tot hier gebracht. Je geest zal je de kracht geven om nog verder te gaan. Maar de eerste stap moet jij zelf zetten.",
  g = { {"tot nu toe", "thus far"}, {"studie", "studies"}, {"zuiverheid", "purity"}, {"oostkust", "east coast"}, {"ten zuiden van", "south of"}, {"vissershut", "fishing hut"}, {"Succes", "good luck"}, {"horizon", "horizon"}, {"verwarmd", "warmed (verwarmen)"}, {"zetten", "to take (a step), to set"} },
},

[2985] = { en = "Call of Water", tier = 1,
  t = "De roep van het water",
  d = "Je lijkt klaar voor je volgende test, $N. Je bent geduldig geweest in je studie, maar nu is het tijd dat je meer leert. Het is tijd dat je leert over de zuiverheid van water.$B$BZoek Islen Waterseer in de Barrens. Ze is aan de oostkust, ten zuiden van de Southfury River en Ratchet. Je vindt haar daar bij haar vissershut. Succes, $N.",
  o = "Zoek Islen Waterseer in de Barrens.",
