  g = { {"volgende", "next"}, {"studie", "studies"}, {"zuiverheid", "purity"}, {"oostkust", "east coast"}, {"ten zuiden van", "south of"}, {"vissershut", "fishing hut"}, {"Succes", "good luck"}, {"horizon", "horizon"}, {"verwarmd", "warmed (verwarmen)"}, {"zetten", "to take (a step), to set"} },
},

